+        this.graph = graph;
+        this.visited = new boolean[graph.getVertexCount()];
+        this.result = new ArrayList<>();
+    }
+
+    public List<Integer> traverse() {
+        for (int i = 0; i < graph.getVertexCount(); i++) {
+            if (!visited[i]) {
+                bfsFromVertex(i);
+            }
+        }
+        return result;
+    }
