+            int current = queue.poll();
+            result.add(current);
+
+            for (int neighbor : graph.getAdjacent(current)) {
+                if (!visited[neighbor]) {
+                    visited[neighbor] = true;
+                    queue.add(neighbor);
+                }
+            }
+        }
+    }
